Loop:
```js class Loop {
 constructor({ stepDt =1 /120, step, draw, hud } = {}) {
 if (typeof step !== 'function' || typeof draw !== 'function')
 throw new Error('WRD.Loop requires step(stepDt) and draw(ctxless) callbacks');
 this.stepDt = stepDt; this.step = step; this.draw = draw; this.hud = hud || null;
 this.playing = false; this._acc =0; this._last = null;
 this._tick = this._tick.bind(this);
 }
 start() { this.playing = true; this._last = null; if (!this._raf) this._raf = requestAnimationFrame(this._tick); }
 pause() { this.playing = false; }
 toggle() { this.playing ? this.pause() : this.start(); }
 reset() { this._acc =0; if (this.onReset) this.onReset(); if (!this._raf) this._raf = requestAnimationFrame(this._tick); }
 _tick(now) {
 this._raf = requestAnimationFrame(this._tick);
 if (this.playing) {
 if (this._last === null) this._last = now;
 this._acc += Math.min((now - this._last) /1000,0.25); this._last = now;
 while (this._acc >= this.stepDt) { this.step(this.stepDt); this._acc -= this.stepDt; }
 } else { this._last = now; }
 this.draw();
 if (this.hud) this.hud();
 WRD.frames++;
 }
 }
```
