drawArrow:
```js function drawArrow(ctx, x1, y1, x2, y2, opts = {}) {
 const color = opts.color || '#e63946';
 const width = opts.width ||3;
 const label = opts.label || '';
 const dx = x2 - x1, dy = y2 - y1;
 const len = Math.hypot(dx, dy);
 if (len <1) return;
 const ux = dx / len, uy = dy / len;
 const head = Math.min(opts.headLen ||10, len *0.5);
 ctx.save();
 ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = width; ctx.lineCap = 'round';
 ctx.beginPath(); ctx.moveTo(x1, y1);
 ctx.lineTo(x2 - ux * head, y2 - uy * head); ctx.stroke();
 ctx.beginPath();
 ctx.moveTo(x2, y2);
 ctx.lineTo(x2 - ux * head - uy * head *0.45, y2 - uy * head + ux * head *0.45);
 ctx.lineTo(x2 - ux * head + uy * head *0.45, y2 - uy * head - ux * head *0.45);
 ctx.closePath(); ctx.fill();
 if (label) {
 ctx.font = opts.labelFont || '14px "Noto Sans CJK SC", sans-serif';
 ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
 const pad =12;
 ctx.fillText(label, x2 + ux * pad, y2 + uy * pad);
 }
 ctx.restore();
 }
```

