Now skating topic.js:

```jswindow.TopicSim = {
 create(cfg, ctx, WRD) {
 const P = cfg.physics; // data from config: mass, mu, thrust, etc.
 let s; // state function reset() { s = { t:0, x:0, v:0, pushT:0, pushing:false }; }
 reset();
 function forces(v) {
 const push = s.pushing ? P.thrust * Math.max(0,1 - v / P.vCap) :0;
 const fr = Math.abs(v) >1e-4 ? P.mu * P.mass *9.8 :0; // opposes motion const drag = P.dragK * v * v; // opposes motion (dragK =0.5ρCdA)
 return { push, fr, drag };
 }
 function step(dt) {
 s.t += dt; s.pushT += dt;
 if (s.pushT >= P.strokeInterval) { s.pushT =0; s.pushing = true; }
 if (s.pushing && s.pushT >= P.strokeDuration) s.pushing = false;
 const f = forces(s.v);
 const dir = s.v >=0 ?1 : -1;
 const net = f.push - dir * f.fr - dir * f.drag;
 s.v += net / P.mass * dt;
 if (Math.abs(s.v) <1e-3 && f.push ===0) s.v =0;
 s.x += s.v * dt;
 }
 // camera + drawing const W = cfg.canvas.width, H = cfg.canvas.height;
 const groundY = H *0.62;
 const pxPerM =28;
 function draw(c) {
 const camX = s.x * pxPerM - W *0.28; // world→screen offset c.clearRect(0,0,W,H);
 // sky gradient ...
 // ice strip with scrolling marks: marks every2 m at world positions // skater at screenX = W*0.28 // arrows: scale = cfg.arrowScale px/N with min length ...
 }
 function hudValues() {
 const f = forces(s.v);
 return [
 {label:'时间', value: s.t.toFixed(1)+' s'},
 {label:'速度', value: s.v.toFixed(2)+' m/s'},
 {label:'滑行距离', value: s.x.toFixed(1)+' m'},
 {label:'蹬冰推力', value: f.push.toFixed(0)+' N'},
 {label:'摩擦力', value: f.fr.toFixed(1)+' N'},
 {label:'空气阻力', value: f.drag.toFixed(1)+' N'},
 {label:'状态', value: s.pushing ? '蹬冰' : '滑行'}
 ];
 }
 return { step, draw, hudValues, reset };
 }
};
```

